            DECLARE
                v_schema text := 'repack';
                v_role   text := 'lisa';
                v_func   record;
                v_tbl    record;
            BEGIN
                -- Check USAGE on repack schema
                privilege_check := 'USAGE ON SCHEMA ' || v_schema;
                granted := has_schema_privilege(v_role, v_schema, 'USAGE');
                RETURN NEXT;

                -- Check CREATE on repack schema
                privilege_check := 'CREATE ON SCHEMA ' || v_schema;
                granted := has_schema_privilege(v_role, v_schema, 'CREATE');
                RETURN NEXT;

                -- Check EXECUTE on each function in repack schema
                FOR v_func IN
                    SELECT p.oid, p.proname
                    FROM pg_catalog.pg_proc p
                    JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace
                    WHERE n.nspname = v_schema
                LOOP
                    privilege_check := 'EXECUTE ON FUNCTION ' || v_schema || '.' || v_func.proname;
                    granted := has_function_privilege(v_role, v_func.oid, 'EXECUTE');
                    RETURN NEXT;
                END LOOP;

                -- Check SELECT, INSERT, UPDATE, DELETE on each table in repack schema
                FOR v_tbl IN
                    SELECT c.oid, c.relname
                    FROM pg_catalog.pg_class c
                    JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
                    WHERE n.nspname = v_schema
                      AND c.relkind IN ('r', 'p')
                LOOP
                    privilege_check := 'SELECT ON TABLE ' || v_schema || '.' || v_tbl.relname;
                    granted := has_table_privilege(v_role, v_tbl.oid, 'SELECT');
                    RETURN NEXT;

                    privilege_check := 'INSERT ON TABLE ' || v_schema || '.' || v_tbl.relname;
                    granted := has_table_privilege(v_role, v_tbl.oid, 'INSERT');
                    RETURN NEXT;

                    privilege_check := 'UPDATE ON TABLE ' || v_schema || '.' || v_tbl.relname;
                    granted := has_table_privilege(v_role, v_tbl.oid, 'UPDATE');
                    RETURN NEXT;

                    privilege_check := 'DELETE ON TABLE ' || v_schema || '.' || v_tbl.relname;
                    granted := has_table_privilege(v_role, v_tbl.oid, 'DELETE');
                    RETURN NEXT;
                END LOOP;
            END;

