            DECLARE
                v_data_dir text := current_setting('data_directory');
            BEGIN
                CREATE TEMP TABLE disk_info(line text) ON COMMIT DROP;

                EXECUTE format(
                    'COPY disk_info FROM PROGRAM %L',
                    'df -hP ' || v_data_dir
                        );

                RETURN QUERY
                    SELECT
                        cols[2],
                        cols[3],
                        cols[4],
                        cols[5]
                    FROM (
                             SELECT regexp_split_to_array(trim(line), '\s+') AS cols
                             FROM disk_info
                             OFFSET 1
                         ) s;
            END;

            BEGIN
                -- Grant usage and create on repack schema
                GRANT USAGE, CREATE
                    ON SCHEMA repack
                    TO lisa;

                -- Grant execute on all functions in repack schema
                GRANT EXECUTE ON ALL FUNCTIONS
                    IN SCHEMA repack
                    TO lisa;

                -- Grant DML on all tables in repack schema
                GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES
                    IN SCHEMA repack
                    TO lisa;

                RETURN 'repack privileges granted successfully';
            END;

            DECLARE
                v_session record;
                v_remaining integer;
            BEGIN
                -- Stop active pg_repack sessions first, otherwise DROP EXTENSION can block for a long time.
                FOR v_session IN
                    SELECT pid
                    FROM pg_stat_activity
                    WHERE pid <> pg_backend_pid()
                      AND state IN ('active', 'idle in transaction', 'idle in transaction (aborted)')
                      AND (
                        application_name ILIKE '%repack%'
                      )
                LOOP
                    PERFORM pg_terminate_backend(v_session.pid);
                END LOOP;

                -- Safety check: do not proceed if pg_repack sessions are still active.
                SELECT COUNT(*)
                INTO v_remaining
                FROM pg_stat_activity
                WHERE pid <> pg_backend_pid()
                  AND state IN ('active', 'idle in transaction', 'idle in transaction (aborted)')
                  AND (
                    application_name ILIKE '%repack%'
                  );

                IF v_remaining > 0 THEN
                    RAISE EXCEPTION 'Cannot reinstall pg_repack: % active pg_repack session(s) still running.', v_remaining;
                END IF;

                -- Remove pg_repack and all extension-owned objects
                DROP EXTENSION IF EXISTS pg_repack CASCADE;

                -- Recreate pg_repack
                CREATE EXTENSION IF NOT EXISTS pg_repack;

                -- Restore required privileges assigned during initial setup of pg_repack extension to run via non-superuser role
                GRANT USAGE, CREATE
                    ON SCHEMA repack
                    TO lisa;

                GRANT EXECUTE ON ALL FUNCTIONS
                    IN SCHEMA repack
                    TO lisa;

                GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES
                    IN SCHEMA repack
                    TO lisa;
                RETURN 'pg_repack successfully reinstalled';
            END;
